using System.Collections;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BloodySolsticeActiveEffect", menuName = "Data/Battle/Effects/Sothis/BloodySolsticeActive Effect")]
public class BloodySolsticeActiveEffect : Effect
{
	[Header("Soul Heat")]
	[SerializeField]
	private VoidEvent OnPlayerLoseHeart;

	[SerializeField]
	private SoulHeat soulHeat;

	[SerializeField]
	private FloatReference delayToUpdateCorruptionMeterFloatReference;

	[SerializeField]
	private FloatReference loseHeartLoseGameVFXDelayFloatReference;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueAfterAction(BloodySolsticeCoroutine(effectAmount, effectOwner));
		instance.SetState(instance.ActionsQueueState);
		return 0;
	}

	private IEnumerator BloodySolsticeCoroutine(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		GameObject vfx = null;
		if (IsVFXEnabled())
		{
			VFXHolder vFXInstanceFromVFXHoldersAndRemoveItFromList = ReferenceSingleton<VFXHandler>.Instance.GetVFXInstanceFromVFXHoldersAndRemoveItFromList(effectOwner, this);
			if (vFXInstanceFromVFXHoldersAndRemoveItFromList != null)
			{
				vfx = vFXInstanceFromVFXHoldersAndRemoveItFromList.VFXInstance;
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(vfx, 4f);
			}
		}
		bool soulHeatRequirementNotMatch = soulHeat.SoulHeatCounter != effectAmount && currentCorruptedAnimals.IsAnyEnemyActive();
		if (soulHeatRequirementNotMatch)
		{
			if (IsVFXEnabled())
			{
				vfx.GetComponent<ParticleEmissionController>().SetActive(value: false);
			}
			yield return new WaitForSeconds(1.5f);
		}
		else
		{
			yield return new WaitForSeconds(0.5f);
		}
		if (soulHeatRequirementNotMatch)
		{
			PlayEffectActivationSFX();
		}
		if (IsVFXEnabled())
		{
			string trigger;
			if (soulHeatRequirementNotMatch)
			{
				OnPlayerLoseHeart.Raise();
				trigger = "LoseHeart";
			}
			else
			{
				vfx.GetComponent<ParticleEmissionController>().SetActive(value: false);
				trigger = "Disable";
			}
			vfx.GetComponentInChildren<Animator>().SetTrigger(trigger);
		}
		else if (soulHeatRequirementNotMatch)
		{
			OnPlayerLoseHeart.Raise();
		}
		if (soulHeatRequirementNotMatch)
		{
			yield return new WaitForSeconds(delayToUpdateCorruptionMeterFloatReference.Value + loseHeartLoseGameVFXDelayFloatReference.Value);
		}
		else
		{
			yield return new WaitForSeconds(0.5f);
		}
		effectOwner.GetComponent<UnitEffects>().IsEffectActiveRemoveEffect(this, activateFeedback: false);
	}

	public override void OnRemoveEffectEndOfBattle(int effectAmount, GameObject effectOwner)
	{
		VFXHolder vFXInstanceFromVFXHoldersAndRemoveItFromList = ReferenceSingleton<VFXHandler>.Instance.GetVFXInstanceFromVFXHoldersAndRemoveItFromList(effectOwner, this);
		if (vFXInstanceFromVFXHoldersAndRemoveItFromList != null)
		{
			GameObject vFXInstance = vFXInstanceFromVFXHoldersAndRemoveItFromList.VFXInstance;
			vFXInstance.GetComponent<ParticleEmissionController>().SetActive(value: false);
			vFXInstance.GetComponentInChildren<Animator>().SetTrigger("Disable");
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(vFXInstance, 4f);
		}
	}
}
